'use strict';
const KEY='five-lectures-v1', VERSION=1, C=window.COURSE;
const CHAPTERS=['第零讲 · 微积分必要基础','第一讲 · 向量代数与矩阵','第二讲 · 方程组理论与空间解析几何','第三讲 · 线性相关性与常微分方程','第四讲 · 特征值理论与多元微分学','第五讲 · 多重积分与级数理论'];
const DAYS=['极限与求导，建立变化的直觉','积分基础，连接变化与累加','向量、投影、面积与体积','矩阵：线性变换的语言','行列式、求逆与分块','消元与秩，数清独立信息','解的存在性与空间直线平面','曲面与线性相关性','解的结构与分离变量','一阶线性与二阶齐次方程','二阶非齐次方程专项','特征值与相似对角化','二次型与线性动力系统','偏导数、链式法则与隐函数','梯度、方向导数与无条件极值','条件极值与最小二乘','多重积分与坐标变换','曲线、曲面积分与Green公式','Gauss、Stokes与级数','综合模拟测试','第二套测试与薄弱点复习'];
const PREREQS={1:'高中函数、指数对数与三角函数',2:'第1天：链式法则与乘积求导',3:'高中坐标与勾股定理',4:'第3天：向量与点积',5:'第4天：矩阵乘法、转置与逆',6:'第4—5天：矩阵运算和可逆性',7:'第3天、第6天：叉积、秩与消元',8:'第3—7天：向量与空间平面',9:'第6、8天：自由变量与无关性；第2天积分',10:'第1—2天微积分、第9天微分方程',11:'第10天：特征根与齐次方程',12:'第5—6天：行列式、齐次方程',13:'第12天：特征值与对角化',14:'第1天：链式法则',15:'第3天点积、第13天二次型、第14天偏导',16:'第6天消元、第14—15天偏导与极值',17:'第2天积分、第8天曲面、第14天偏导',18:'第3天叉积、第8天参数曲线、第17天二重积分',19:'第18天曲面积分、第1天极限与第2天积分',20:'第1—19天主线；有困难可先查错题本',21:'第20天测试反馈'};
const defaultState=()=>({version:VERSION,done:[],favorites:[],attempts:{},notes:{},last:'limit',activeDay:1,studySeconds:0,examRuns:[],updated:new Date().toISOString()});
let state=defaultState(), storageOK=true;
try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s&&s.version===VERSION)state={...state,...s};}catch(e){storageOK=false;}
let currentId=null, examSession=null, toastTimer, renderedAt=Date.now();
const byId=id=>C.find(x=>x.id===id);
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function rich(s){return String(s??'').split(/(\$[^$]+\$)/g).map(part=>{if(part.startsWith('$')&&part.endsWith('$')){const tex=part.slice(1,-1).replace(/′/g,'\\prime ');try{return '<span class="math">'+katex.renderToString(tex,{throwOnError:true,strict:'ignore',trust:false,output:'htmlAndMathml'})+'</span>'}catch(e){return '<span class="math math-error" title="公式未能渲染">'+esc(tex)+'</span>'}}return esc(part);}).join('');}
function P(s){return '<p>'+rich(s)+'</p>';}
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;toast('浏览器未能保存记录，请导出进度备份。');}updateSide();}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3800);}
function wrongKeys(){return Object.keys(state.attempts).filter(k=>state.attempts[k]?.wrong>0&&!state.attempts[k]?.resolved);}
function updateSide(){const n=state.done.length;$('#side-progress').textContent=`已学 ${n} / ${C.length} 节 · ${Math.round(n/C.length*100)}%`;$('#side-bar').style.width=n/C.length*100+'%';$('#wrong-count').textContent=wrongKeys().length;}
function pagesLabel(l){if(!l.pages.length)return '补充讲解 · PDF未设此章';return `讲义印刷 p.${l.pages.length===2?l.pages.join('—'):l.pages.join('、')} · PDF文件第${l.pages[0]+4}页起`;}
function sourceLink(l){return l.pages.length?`<a class="text-link" href="source.pdf#page=${l.pages[0]+4}" target="_blank" rel="noopener">${pagesLabel(l)} ↗</a>`:`<span class="meta">${pagesLabel(l)}</span>`;}
function sprintForLesson(l){return window.SPRINT?.find(s=>s.lessons.includes(l.id));}
function learningDayLabel(l){const d=sprintForLesson(l);return d?`冲刺第${d.day}天`:`基础回顾 · 原计划第${l.day}天`;}
function card(l){return `<a class="lesson-card ${state.done.includes(l.id)?'done':''}" href="#lesson/${l.id}"><span class="lesson-icon">${state.done.includes(l.id)?'✓':l.chapter[0]==='0'?'∂':l.chapter[0]==='5'?'∫':'𝑥'}</span><div class="grow"><h3>${esc(l.title)}</h3><div class="meta">${esc(l.chapter)} · ${learningDayLabel(l)} · ${l.pages.length?'讲义 p.'+l.pages[0]:'补充讲解'}</div></div><span class="arrow">↗</span></a>`;}
function heading(k,title,sub){return `<div class="page-heading"><span class="eyebrow">${k}</span><h1>${title}</h1>${sub?P(sub):''}</div>`;}
function heroSvg(){return `<svg viewBox="0 0 430 260" aria-hidden="true"><defs><pattern id="hero-grid" width="31" height="31" patternUnits="userSpaceOnUse"><path d="M31 0H0V31" fill="none" stroke="#9ab899" stroke-width=".45" opacity=".23"/></pattern><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#c5df92" stop-opacity=".27"/><stop offset="1" stop-color="#c5df92" stop-opacity=".02"/></linearGradient></defs><rect width="430" height="260" fill="url(#hero-grid)"/><path d="M45 221H396M92 243V20" stroke="#95b992" stroke-width="1" opacity=".6"/><path d="M45 212C108 211 113 185 160 180S218 197 250 144S290 76 370 46V221H45Z" fill="url(#area)"/><path d="M45 212C108 211 113 185 160 180S218 197 250 144S290 76 370 46" stroke="#c2de8e" fill="none" stroke-width="2.3"/><path d="M176 220L321 70" stroke="#86ada3" stroke-dasharray="5 5"/><circle cx="250" cy="144" r="5" fill="#d3e7ae"/><path d="M250 144V221M92 144H250" stroke="#b8d28b" stroke-dasharray="3 6" opacity=".6"/><text x="261" y="143" fill="#cce2af" font-family="Georgia" font-size="15">f(x)</text><text x="395" y="239" fill="#8fab94" font-size="13">x</text><text x="73" y="25" fill="#8fab94" font-size="13">y</text></svg>`;}
function homeOriginal(){const next=byId(state.last)||C.find(l=>!state.done.includes(l.id))||C[0];const d=next.day;const today=C.filter(l=>l.day===d);const solved=Object.values(state.attempts).filter(a=>a.resolved).length;return `<div class="intro-line"><span class="eyebrow">YOUR QUIET SPACE TO LEARN</span><span class="date-badge">21天 · 每天3—4小时</span></div>${heading('','把抽象的数学，<br>一点一点弄明白。','从一个问题出发，跟着每一步推导，走到自己的答案。')}<section class="hero"><div class="hero-copy"><span class="eyebrow">从上次停下的地方继续 / DAY ${String(d).padStart(2,'0')}</span><h2>${d===1?'先理解「变化」，<br>再认识微积分。':esc(DAYS[d-1])}</h2><p>${esc(next.title)}<br>概念讲解 · 分步推导 · 交互实验 · 随堂练习</p><a class="btn light" href="#lesson/${next.id}">继续学习 <span>→</span></a></div><div class="hero-graph">${heroSvg()}<span class="graph-label">small steps, clear ideas.</span></div></section><div class="stats"><div class="stat"><span class="stat-label">课程学习进度</span><div class="stat-num">${state.done.length}<small>/ ${C.length}节</small></div><span class="stat-icon">◷</span></div><div class="stat"><span class="stat-label">已掌握的练习</span><div class="stat-num">${solved}<small>/ ${exerciseTotal()}题</small></div><span class="stat-icon">✓</span></div><div class="stat"><span class="stat-label">待回看的错题</span><div class="stat-num">${wrongKeys().length}<small>道</small></div><span class="stat-icon">✎</span></div><div class="stat"><span class="stat-label">页面可见时长</span><div class="stat-num">${Math.floor(state.studySeconds/60)}<small>分钟</small></div><span class="stat-icon">⌁</span></div></div><div class="two-col"><section><div class="section-heading"><div><h2>今天，从这里开始</h2><p>DAY ${String(d).padStart(2,'0')} · ${DAYS[d-1]}</p></div><a class="text-link" href="#day/${d}">完整安排 →</a></div><div class="lesson-list">${today.map(card).join('')}</div></section><section><div class="section-heading"><h2>三周，走完五讲</h2><a class="text-link" href="#plan">查看计划 →</a></div><div class="panel"><span class="eyebrow">第一周 / 基础与线性代数</span><div class="day-strip">${Array.from({length:7},(_,i)=>`<a class="day-chip ${d===i+1?'active':''}" href="#day/${i+1}">DAY<b>${String(i+1).padStart(2,'0')}</b>${C.filter(l=>l.day===i+1).every(l=>state.done.includes(l.id))?'✓':'·'}</a>`).join('')}</div><p class="small muted" style="margin-top:19px">先学必学主线，再展开证明。第20—21天用测试与错题定位薄弱点。</p><div class="tip">看不懂的那一步，可以先记下来。每节课都有“向 ChatGPT 提问”，会带上公式和讲义页码。</div></div></section></div><div class="section-heading"><h2>把公式变成看得见的东西</h2><a href="#lab" class="text-link">进入数学实验室 →</a></div><div class="mini-grid"><a class="panel" href="#lab/derivative"><span class="eyebrow">微积分实验</span><h3 style="margin-top:10px">割线，怎样慢慢变成切线？</h3><span class="small muted">拖动增量h，观察斜率与极限。</span></a><a class="panel" href="#lab/matrix"><span class="eyebrow">线性代数实验</span><h3 style="margin-top:10px">一张网格，理解矩阵变换。</h3><span class="small muted">旋转、伸缩、剪切与有向面积。</span></a></div>${!storageOK?'<div class="note">当前浏览器限制本地存储，请使用进度备份功能。</div>':''}`;}
function dayCard(d){const lessons=C.filter(l=>l.day===d),done=lessons.filter(l=>state.done.includes(l.id)).length;return `<a href="#day/${d}" class="day-card"><div class="actions"><span class="num">${String(d).padStart(2,'0')}</span><span class="tag">${d<=7?'基础阶段':d<=14?'进阶阶段':d<=19?'综合阶段':'考试复习'}</span></div><h3>${DAYS[d-1]}</h3><p>${d<=19?lessons.map(l=>l.chapter).join(' / '):d===20?'18题 · 90分钟 · 全面检验':'12题 · 60分钟 · 错题回炉'}</p><div class="card-bottom"><span>约${d===2||d>=17&&d<=19?'240':'210'}分钟</span><span>${d<=19?`${done}/${lessons.length}节已完成`:'测试 + 复盘'} →</span></div></a>`;}
function plan(){return heading('21-DAY LEARNING PATH','21天，一步一步来。','以每天3—4小时为初始安排。证明和进阶解释可在主线学完后展开；若练习未通过，先回看再前进。')+`<div class="tip">第2、17—19天较密集：优先完成概念、主要例题和基础题；综合题与长证明放入晚间或第21天复习。课程量较大，时间安排需按实际掌握情况调整。</div><div class="tabs" style="margin-top:22px"><a href="#plan" class="active">全部21天</a><a href="#chapters">切换为按章节学习</a></div><div class="day-grid">${Array.from({length:21},(_,i)=>dayCard(i+1)).join('')}</div>`;}
function dayPage(d){if(d<1||d>21)return notFound();const ls=C.filter(l=>l.day===d);state.activeDay=d;save();if(d>=20)return reviewPage(d);const previous=d===1?null:C.filter(l=>l.day===d-1);return heading(`DAY ${String(d).padStart(2,'0')} / 21`,DAYS[d-1],`先修要求：${PREREQS[d]}。`)+`<div class="day-layout"><div><div class="panel" style="margin-bottom:20px"><h3>今天要真正弄明白的事</h3><p class="small">${ls.map(l=>l.goals[0]).join('；')}。</p><div class="tip">完成标准：能脱离答案重做本日主要例题，并完成每节基础题。点击“标记已学”记录你的判断，系统不会仅凭浏览自动判为掌握。</div></div><div class="lesson-list">${ls.map(card).join('')}</div><div class="panel" style="margin-top:20px"><h3>离开前的复习</h3><ol class="small proof-list"><li>合上推导，用自己的话解释每节的定义与符号。</li><li>不看答案重做一个本日例题，写出所有中间步骤。</li><li>查看今天做错的题，定位是概念、公式还是运算问题。</li><li>${previous?'快速回想昨天的“'+esc(previous[0].goals[0])+'”，并重做一题。':'用导数定义与求导法则各做一次平方函数，比较两种路径。'}</li></ol><div class="actions"><a class="btn secondary" href="#mistakes">去错题本</a><a class="btn" href="#day/${d+1}">下一天 →</a></div></div></div><aside class="panel"><h3>今天的学习节奏</h3><ol class="schedule"><li><b>10分钟 · 唤醒记忆</b><p>复习先修知识和昨天的一道题。</p></li><li><b>${d===2||d>=17?'110':'80'}分钟 · 概念与推导</b><p>按目录顺序阅读必学部分，写下每个符号的含义。</p></li><li><b>45分钟 · 例题拆解</b><p>逐步展开答案；每看一步前先自己尝试。</p></li><li><b>50分钟 · 分层练习</b><p>先基础题、再典型题，余力做综合题。</p></li><li><b>25分钟 · 复盘</b><p>回看错题，口述方法，标记已学。</p></li></ol><p class="small muted">约${d===2||d>=17?'240':'210'}分钟。每学习45—50分钟休息5—10分钟，休息时间另计。</p></aside></div>`;}
function chaptersFull(){return heading('THE COMPLETE COURSE','按章节，找到知识的位置。','保留讲义原有章节编号。第零讲及文中标明的延伸知识为补充讲解；页码为正文印刷页码，PDF文件页码=印刷页码+4。')+CHAPTERS.map((name,i)=>`<section class="chapter-block" id="chapter-${i}"><div class="section-heading"><h2>${name}</h2><span class="tag">${C.filter(l=>l.chapter.startsWith(String(i))).length}节详解</span></div><div class="lesson-list">${C.filter(l=>l.chapter.startsWith(String(i))).map(card).join('')}</div></section>`).join('');}
function stepsHTML(items,n=items.length){return `<ol class="step-group">${items.slice(0,n).map(t=>`<li><div>${rich(t)}</div></li>`).join('')}</ol>`;}
function exerciseHTML(l,index,exam=false){const ex=l.exercises[index],key=l.id+':'+index,a=state.attempts[key];return `<div class="exercise" data-key="${key}" data-level="${ex.level}" ${exam?'data-exam="true"':''}><div class="level">${ex.level} ${exam?'· 测试题':''}${!exam&&a?.resolved?' · ✓ 已答对':''}</div><div class="question-text">${rich(ex.q)}</div><div class="answer-row"><input aria-label="${esc(ex.level)}答案" placeholder="数值、分数或算式，如 1/6" inputmode="text" autocomplete="off" ${!exam&&a?.lastInput?`value="${esc(a.lastInput)}"`:''}><button class="btn small" data-check>检查答案</button></div><div class="feedback" role="status" aria-live="polite"></div>${!exam?`<div class="actions"><button class="btn secondary small" data-hint>提示下一步</button><button class="btn secondary small" data-ask-ex="${key}">带着此题提问 ↗</button></div><div class="hint-area small"></div><details><summary>查看完整答案与过程</summary>${stepsHTML(ex.solution)}<p class="small">数值检查点：${esc(ex.answer)}。</p></details>`:''}</div>`;}
function lessonPage(l){if(!l)return notFound();currentId=l.id;state.last=l.id;save();const ix=C.indexOf(l),done=state.done.includes(l.id);return `<div class="lesson-heading"><span class="eyebrow">${learningDayLabel(l)} · ${esc(l.chapter)}${l.chapter.startsWith('0')?' · 补充讲解':''}</span><h1>${esc(l.title)}</h1>${sourceLink(l)}<div class="actions"><button class="btn ${done?'subtle':''}" id="mark-done">${done?'✓ 已标记已学':'标记本节已学'}</button><button class="btn secondary" id="favorite">${state.favorites.includes(l.id)?'★ 已收藏':'☆ 收藏本节'}</button><button class="btn secondary" id="ask-top">向 ChatGPT 提问 ↗</button><button class="btn secondary" onclick="window.print()">打印本节</button></div></div><div class="reading-layout"><article class="article"><section id="goals"><h2><span class="section-number">00</span>这节课，要学会什么</h2><ul class="goal-list">${l.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul></section><section id="concept"><h2><span class="section-number">01</span>从一个问题开始</h2>${l.concept.map(P).join('')}</section><section id="slow-notes"><details class="deep"><summary>先把这一步弄明白 · 展开更细的解释</summary>${l.slowNotes.map(P).join('')}</details></section><section id="symbols"><h2><span class="section-number">02</span>先把符号读懂</h2><table class="symbol-table"><tbody>${l.symbols.map(s=>`<tr><td>${rich(s[0])}</td><td>${rich(s[1])}</td></tr>`).join('')}</tbody></table></section><section id="derivation"><h2><span class="section-number">03</span>公式，一步一步来</h2><div class="steps" id="derive-steps" data-steps="derive">${stepsHTML(l.derive,1)}</div><div class="actions"><button class="btn secondary small" data-next-step="derive">展示下一步</button><button class="text-link quiet" data-all-step="derive">一次展开全部</button></div></section><section id="visual"><h2><span class="section-number">04</span>动手，让概念看得见</h2>${labHTML(l.visual,l.id)}</section><section id="example"><h2><span class="section-number">05</span>例题，完整走一遍</h2><div class="example-box"><span class="eyebrow">${l.pages.length?'讲义相关例题 / 题号与页码见下':'补充例题'}</span>${P(l.example)}</div><div class="steps" id="example-steps" data-steps="example">${stepsHTML(l.steps,1)}</div><div class="actions"><button class="btn secondary small" data-next-step="example">展示下一步计算</button><button class="text-link quiet" data-all-step="example">一次展开全部</button></div>${l.moreExamples?.length?`<div class="more-examples">${l.moreExamples.map(e=>`<details class="deep" style="margin-top:16px"><summary>${esc(e.title)}</summary>${P(e.q)}${stepsHTML(e.steps)}</details>`).join('')}</div>`:''}</section><section id="slow-example"><details class="deep"><summary>新增慢速演算 · 看清每次代入与化简</summary>${P(l.slowExample.q)}${stepsHTML(l.slowExample.steps)}</details></section><section id="practice"><h2><span class="section-number">06</span>现在，自己试一试</h2><p class="small muted">在纸上写完整过程，再输入题目要求的数值检查点。自动检查只验证这个数值，不替代对推导过程的检查。</p><div class="practice-filters" role="group" aria-label="按难度筛选练习">${['全部','基础题','典型题','综合题'].map((t,i)=>`<button class="btn small ${i?'secondary':''}" data-practice-filter="${t}">${t} · ${i?l.exercises.filter(e=>e.level===t).length:l.exercises.length}</button>`).join('')}</div><p class="small muted">时间紧时，先进入紧凑路线完成本日3道核心题。这里的9题用于按需巩固。</p>${l.exercises.map((_,i)=>exerciseHTML(l,i)).join('')}</section><section id="errors"><h2><span class="section-number">07</span>易错点与考试方法</h2><ul class="error-list">${l.errors.filter(Boolean).map(e=>`<li>${rich(e)}</li>`).join('')}</ul><div class="tip" style="margin-top:20px">本节方法自检：${l.goals.map(esc).join(' → ')}。请合上答案，用自己的话说一遍。</div></section><section id="deep"><details class="deep"><summary>深入理解 · 证明、条件与进阶解释</summary>${P(l.deep)}</details></section><section id="notes"><h2>留给自己的笔记</h2><textarea id="lesson-note" aria-label="本节笔记" placeholder="记下你卡住的那一步，或用自己的话解释一个概念…">${esc(state.notes[l.id]||'')}</textarea><div class="small muted" style="margin-top:8px">笔记自动保存在当前浏览器；跨设备学习请先导出备份。</div></section></article><aside class="sticky-rail"><div class="rail-box toc-box"><h3>本节导航</h3><nav class="toc">${[['goals','学习目标'],['concept','概念讲解'],['symbols','符号说明'],['derivation','逐步推导'],['visual','交互实验'],['example','例题详解'],['practice','分层练习'],['errors','易错点'],['deep','深入理解']].map(([id,t])=>`<a href="#${id}" data-scroll="${id}">${t}</a>`).join('')}</nav></div><div class="rail-box" id="ask-box"><h3>向 ChatGPT 提问</h3><p class="small muted">把卡住的地方带回聊天里。</p><textarea id="ask-question" class="ask-input" aria-label="输入你想向ChatGPT提问的问题" placeholder="例如：为什么这一步可以约去x−1？"></textarea><button class="btn small full-width" id="copy-question">复制完整提问</button><p class="offline-note" style="margin:9px 0 0">包含标题、公式、例题与页码。请自行粘贴到聊天，不会同步聊天记录。</p></div><div class="rail-box"><h3>回到学习路径</h3><a class="text-link" href="${sprintForLesson(l)?'#sprint/'+sprintForLesson(l).day:'#day/'+l.day}">${learningDayLabel(l)} · 每日安排 →</a><div style="margin-top:12px">${sourceLink(l)}</div></div></aside></div><div class="reading-bottom">${ix>0?`<a class="btn secondary" href="#lesson/${C[ix-1].id}">← 上一节</a>`:'<a class="btn secondary" href="#day/1">← 第一天</a>'}${ix<C.length-1?`<a class="btn" href="#lesson/${C[ix+1].id}">下一节：${esc(C[ix+1].title.split('：')[0])} →</a>`:'<a class="btn" href="#day/20">进入模拟测试 →</a>'}</div>`;}
const LABS={limit:['极限观察窗','保持x≠1，观察x向1靠近时函数值如何接近2。'],derivative:['从割线到切线','拖动h，比较割线斜率2+h与切线斜率2。'],integral:['面积的累加','以f(x)=x²为例，右端点矩形和随分割加密趋向1/3。此实验演示定积分，不用于替代换元或分部计算。'],vectors:['向量与投影','改变b的方向，观察点积符号和b在a方向的投影。固定a=(3,0)，b的长度为2。'],cross:['叉积与有向面积','两向量位于xy平面。改变夹角，观察法向z分量及面积；右手规则决定正负。'],matrix:['矩阵变换网格','先剪切再旋转：A=Rθ·S。观察方格变成平行四边形，行列式始终为1。'],elimination:['高斯消元实验室','输入矩阵，逐步查看行化简。若输入的是增广矩阵，最后一列会跟随消元；求系数秩时请单独输入系数矩阵。'],geometry:['空间几何切片','拖动z高度，观察单位球与水平面的交圆。用投影图理解三维，不把投影长度当空间真实长度。'],ode:['指数模态与振荡','切换基本解形状，观察系数对增长、衰减或振荡的影响。'],eigen:['寻找不转向的方向','对A=(2,1;1,2)，比较输入v与输出Av。在45°或135°处它们共线。'],gradient:['等高线、梯度与方向','曲面f=x²+y²在(1,1)的梯度(2,2)。拖动单位方向，观察方向导数。'],regression:['用残差看最小二乘','数据点(0,1),(1,2),(2,2)。调整斜率a与截距b，让残差平方和尽可能小。'],region:['积分区域与坐标','比较单位圆盘和三角形，用阴影辨认区域、面积元和积分界限。'],line:['沿曲线的方向与弧长','单位圆弧从角度0走到θ。弧长不随反向变号，环流∫xdy−ydx会变号。'],surface:['曲面法向与通量','对z=ax+by上的单位正方形，F=(0,0,1)。观察面积与向上通量的区别。'],series:['部分和与函数近似','观察几何级数与eˣ的Taylor部分和。n变大是否一定带来收敛，要看x所在的范围。']};
function range(name,label,min,max,value,step=1){return `<label>${label}<input type="range" data-param="${name}" min="${min}" max="${max}" step="${step}" value="${value}" aria-label="${label}"><output>${value}</output></label>`;}
function select(name,label,opts){return `<label>${label}<select data-param="${name}" aria-label="${label}">${opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></label>`;}
function labHTML(type,context='lab'){let controls='';switch(type){case'limit':controls=range('h','与1的距离 h',-1,1,.4,.01);break;case'derivative':controls=range('h','增量 h',-.9,1.6,1,.01);break;case'integral':controls=range('n','矩形数 n',2,80,8);break;case'vectors':case'cross':controls=range('angle','b的角度',-180,180,60);break;case'matrix':controls=range('angle','旋转角度',-180,180,25)+range('shear','剪切系数',-1.5,1.5,.4,.1);break;case'elimination':return `<div class="lab-stage" data-lab="elimination"><h3>${LABS[type][0]}</h3><p class="lab-explain">${LABS[type][1]}</p><textarea class="matrix-entry" aria-label="输入矩阵，每行换行，元素用空格分开">2 1 3 0
1 1 1 0</textarea><div class="actions"><button class="btn small" data-rref>计算行最简形</button><button class="btn secondary small" data-rref-example>载入例2.3</button></div><div class="lab-output" role="status">点击计算，查看主元与每一步行操作。输入数字或分数，最多8行10列。</div><div class="rref-steps"></div></div>`;case'geometry':controls=range('z','截面高度 z',-1,1,.5,.05);break;case'ode':controls=select('mode','解的形式',[['exp','指数 e^(kt)'],['sin','振荡 sin(kt)'],['repeat','重根 t·e^(kt)']])+range('k','参数 k',-2,2,1,.1);break;case'eigen':controls=range('angle','输入向量角度',0,180,25);break;case'gradient':controls=range('angle','行走方向角度',0,360,45);break;case'regression':controls=range('a','斜率 a',-1,2,.5,.05)+range('b','截距 b',-1,3,1.2,.05);break;case'region':controls=select('shape','区域',[['triangle','x≥0,y≥0,x+y≤1'],['disk','单位圆盘']])+range('n','网格数',4,24,10);break;case'line':controls=range('angle','终止角度',0,360,90)+select('direction','行走方向',[['1','正向'],['-1','反向']]);break;case'surface':controls=range('a','平面参数 a',-2,2,1,.1)+range('b','平面参数 b',-2,2,1,.1)+select('sign','法向',[['1','向上'],['-1','向下']]);break;case'series':controls=select('mode','部分和',[['exp','eˣ的Taylor展开'],['geo','几何级数 Σxⁿ']])+range('x','x',-1.5,1.5,1,.05)+range('n','最高次数 n',0,20,4);break;}
return `<div class="lab-stage" data-lab="${type}"><h3>${LABS[type][0]}</h3><p class="lab-explain">${LABS[type][1]}</p><div class="lab-canvas" aria-live="off"></div><div class="controls">${controls}</div><div class="lab-output" role="status" aria-live="polite"></div></div>`;}
const num=(v,d=4)=>Math.abs(v)<1e-10?'0':Number(v.toFixed(d)).toString();
function svgBase(body,desc){return `<svg viewBox="0 0 560 300" role="img" aria-label="${esc(desc)}"><defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#dae4d2" stroke-width=".5"/></pattern><marker id="arrowgreen" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#387b61"/></marker><marker id="arrowblue" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6Z" fill="#7599ac"/></marker></defs><rect width="560" height="300" fill="url(#grid)"/>${body}</svg>`;}
function plot(points,color='#36765e',width=2){return `<polyline points="${points.filter(p=>p.every(Number.isFinite)).map(p=>p.map(x=>num(x,2)).join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width="${width}"/>`;}
function line(x1,y1,x2,y2,color='#83a078',dash=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color}" stroke-width="1.5" ${dash?'stroke-dasharray="'+dash+'"':''}/>`;}
function arrow(x1,y1,x2,y2,color='green'){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${color==='green'?'#387b61':'#7599ac'}" stroke-width="2.4" marker-end="url(#arrow${color})"/>`;}
function textAt(x,y,t,color='#708366'){return `<text x="${x}" y="${y}" fill="${color}" font-family="sans-serif" font-size="12">${esc(t)}</text>`;}
function circle(x,y,r=4,color='#36765e'){return `<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;}
function drawLab(el){const type=el.dataset.lab;if(type==='elimination')return;const get=name=>el.querySelector(`[data-param="${name}"]`);const v=name=>Number(get(name)?.value);const mode=name=>get(name)?.value;let body='',out='';
if(['limit','derivative','integral','ode','series'].includes(type)){
const cx=80,cy=245,sx=125,sy=75;const xy=(x,y)=>[cx+x*sx,cy-y*sy];body=line(30,cy,535,cy)+line(cx,280,cx,20)+textAt(530,265,'x')+textAt(57,20,'y');
let fn=x=>x*x,xmin=-.3,xmax=2.5;
if(type==='limit')fn=x=>x+1;
if(type==='ode'){const k=v('k');fn=mode('mode')==='exp'?x=>Math.exp(k*x):mode('mode')==='sin'?x=>Math.sin(k*x):x=>x*Math.exp(k*x);xmin=0;xmax=3.3;out=`${mode('mode')==='exp'?'y=e^(kt)':mode('mode')==='sin'?'y=sin(kt)':'y=t·e^(kt)'}；k=${k}。曲线超过窗口时已裁切显示。`;}
if(type==='series'){let x=v('x'),n=v('n'),sum=1,term=1;for(let i=1;i<=n;i++){term*=mode('mode')==='exp'?x/i:x;sum+=term;}fn=t=>{let s=1,a=1;for(let i=1;i<=n;i++){a*=mode('mode')==='exp'?t/i:t;s+=a;}return s;};xmin=-.3;xmax=2.5;const target=mode('mode')==='exp'?Math.exp(x):Math.abs(x)<1?1/(1-x):null;out=`n=${n}，x=${x}：部分和=${num(sum,7)}。${target===null?'|x|≥1，几何级数不收敛。':`目标值=${num(target,7)}，绝对误差=${num(Math.abs(sum-target),7)}。`}`;const dot=xy(x,sum);if(dot[0]>0&&dot[1]>0&&dot[1]<300)body+=circle(...dot);}
const points=[];for(let i=0;i<=180;i++){const x=xmin+(xmax-xmin)*i/180;const y=fn(x);const pt=xy(x,Math.max(-.4,Math.min(3,y)));points.push(pt);}body+=plot(points);
if(type==='limit'){let h=v('h');if(Math.abs(h)<.005)h=.01;const p=xy(1+h,2+h),hole=xy(1,2);body+=`<circle cx="${hole[0]}" cy="${hole[1]}" r="5" stroke="#36765e" stroke-width="2" fill="#fbfcf8"/>`+circle(...p)+line(p[0],p[1],p[0],cy,'#7899aa','4 4')+textAt(p[0]+9,p[1]-10,`x=${num(1+h,2)}`);out=`x=${num(1+h,4)}（保持x≠1），f(x)=x+1=${num(2+h,4)}；函数值距离2为${num(Math.abs(h),4)}。空心点表示原函数在x=1处未定义。`;}
if(type==='derivative'){let h=v('h');const slope=2+h;const a=xy(1,1),b=xy(1+h,(1+h)**2);body+=plot([xy(0,-1),xy(2.6,4.2)],'#b0b99d',1.5);const s1=xy(0,1-slope),s2=xy(2.4,1+slope*1.4);body+=plot([s1,s2],'#7599ac')+circle(...a)+circle(...b)+textAt(335,45,'绿：曲线    蓝：割线');out=h===0?'h=0时差商本身无定义；它的极限为2，也就是切线斜率。':`h=${num(h,2)}，Δy=${num(2*h+h*h)}，割线斜率Δy/h=2+h=${num(slope)}；切线斜率=2。`;}
if(type==='integral'){const n=v('n');let sum=0;for(let i=0;i<n;i++){const x=i/n,y=((i+1)/n)**2,p=xy(x,y);sum+=y/n;body+=`<rect x="${p[0]}" y="${p[1]}" width="${sx/n}" height="${cy-p[1]}" fill="#9bbf7060" stroke="#90ac6a" stroke-width=".6"/>`;}body+=plot(points);out=`右端点矩形和 S${n}=${num(sum,6)}；精确积分=1/3≈0.333333；误差=${num(sum-1/3,6)}。这里使用右端点，所以对递增函数会偏大。`;}
}
if(['vectors','cross','eigen','gradient'].includes(type)){
const angle=v('angle')*Math.PI/180,cx=265,cy=165,s=45;body=line(30,cy,530,cy)+line(cx,280,cx,20);let ax=3,ay=0,bx=2*Math.cos(angle),by=2*Math.sin(angle);
if(type==='eigen'){ax=Math.cos(angle);ay=Math.sin(angle);bx=2*ax+ay;by=ax+2*ay;body+=arrow(cx,cy,cx+ax*s,cy-ay*s)+arrow(cx,cy,cx+bx*s,cy-by*s,'blue');const cross=ax*by-ay*bx;out=`v=(${num(ax,3)},${num(ay,3)})，Av=(${num(bx,3)},${num(by,3)})。二维叉积=${num(cross,5)}；为0时共线。在45°处λ=3，在135°处λ=1。`;body+=textAt(35,30,'绿：v   蓝：Av');}
else if(type==='gradient'){const x=265,y=165;for(let r=30;r<=150;r+=30)body+=`<circle cx="195" cy="225" r="${r}" fill="none" stroke="#d5e0c6"/>`;body+=circle(x,y)+arrow(x,y,x+75,y-75)+arrow(x,y,x+90*Math.cos(angle),y-90*Math.sin(angle),'blue')+textAt(30,30,'等高线示意 · 绿：梯度  蓝：单位方向');out=`单位方向e=(${num(Math.cos(angle),3)},${num(Math.sin(angle),3)})；方向导数(2,2)·e=${num(2*Math.cos(angle)+2*Math.sin(angle),5)}；最大值2√2≈2.828427。`;}
else{body+=arrow(cx,cy,cx+ax*s,cy-ay*s)+arrow(cx,cy,cx+bx*s,cy-by*s,'blue')+textAt(cx+ax*s+7,cy-5,'a')+textAt(cx+bx*s+7,cy-by*s-8,'b');if(type==='vectors'){body+=line(cx+bx*s,cy-by*s,cx+bx*s,cy,'#88a473','5 4')+line(cx,cy,cx+bx*s,cy,'#adc77f');out=`a·b=6 cosθ=${num(3*bx)}；b投影到a方向为(${num(bx)},0)。当θ=±90°时点积为0。`;}
else{const poly=`${cx},${cy} ${cx+ax*s},${cy} ${cx+(ax+bx)*s},${cy-by*s} ${cx+bx*s},${cy-by*s}`;body=`<polygon points="${poly}" fill="#b0cb8545"/>`+body;out=`a×b=(0,0,6sinθ)=(0,0,${num(3*by)})；平行四边形面积=${num(Math.abs(3*by))}，三角形面积=${num(Math.abs(3*by)/2)}。z分量的正负由右手规则决定。`;}}
}
if(type==='matrix'){const th=v('angle')*Math.PI/180,k=v('shear'),co=Math.cos(th),si=Math.sin(th);const A=[co,co*k-si,si,si*k+co],xy=(x,y)=>[280+45*x,150-45*y],tr=(x,y)=>xy(A[0]*x+A[1]*y,A[2]*x+A[3]*y);for(let i=-3;i<=3;i++){body+=plot([tr(i,-3),tr(i,3)],'#b7cda4',1)+plot([tr(-3,i),tr(3,i)],'#b7cda4',1);}const q=[[0,0],[1,0],[1,1],[0,1]].map(p=>tr(...p));body+=`<polygon points="${q.map(p=>p.join(',')).join(' ')}" fill="#aacd7055" stroke="#749657"/>`+line(20,150,540,150)+line(280,280,280,20)+arrow(280,150,...tr(1,0))+arrow(280,150,...tr(0,1),'blue');out=`A=(${num(A[0],3)}, ${num(A[1],3)} ; ${num(A[2],3)}, ${num(A[3],3)})；detA=${num(A[0]*A[3]-A[1]*A[2],5)}。绿箭头=Ae₁，蓝箭头=Ae₂。`;}
if(type==='geometry'){const z=v('z'),r=Math.sqrt(Math.max(0,1-z*z));body=`<ellipse cx="280" cy="155" rx="115" ry="36" fill="none" stroke="#ccd9bd"/><circle cx="280" cy="155" r="115" fill="#edf2e840" stroke="#b4c69e"/><ellipse cx="280" cy="${155-z*110}" rx="${r*115}" ry="${r*34}" fill="#bad69266" stroke="#5d8f65"/>`+line(280,285,280,20)+textAt(294,155-z*110,`z=${num(z,2)}`);out=`球面x²+y²+z²=1，在高度z=${num(z,2)}处：x²+y²=${num(1-z*z)}，截面半径=${num(r,5)}。|z|=1时圆缩为一个点。`;}
if(type==='regression'){const a=v('a'),b=v('b'),xy=(x,y)=>[100+x*150,260-y*65],data=[[0,1],[1,2],[2,2]];body=line(60,260,520,260)+line(100,280,100,20)+plot([xy(-.2,b-a*.2),xy(2.5,a*2.5+b)],'#7599ac');let sse=0;for(const [x,y]of data){const p=xy(x,y),q=xy(x,a*x+b);body+=line(...p,...q,'#b58e5d','4 4')+circle(...p);sse+=(y-(a*x+b))**2;}out=`直线y=${num(a,2)}x+${num(b,2)}；残差平方和S=${num(sse,6)}。最优a=1/2、b=7/6，最小S=1/6≈0.166667。拖动滑块为近似值。`;}
if(type==='region'){const xy=(x,y)=>[150+180*x,245-180*y],n=v('n');body=line(70,245,500,245)+line(150,280,150,25);if(mode('shape')==='triangle'){body+=`<polygon points="150,245 330,245 150,65" fill="#b6cc884d" stroke="#6f985b"/>`;for(let i=1;i<n;i++){const x=i/n;body+=line(...xy(x,0),...xy(x,1-x),'#9db482');}out='三角区域：0≤x≤1，0≤y≤1−x；面积1/2。竖条内层对y积分，外层对x积分。网格只帮助看区域，计算以积分公式为准。';}else{body+=`<circle cx="280" cy="150" r="110" fill="#b6cc884d" stroke="#6f985b"/>`;for(let i=0;i<n;i++){const t=2*Math.PI*i/n;body+=line(280,150,280+110*Math.cos(t),150-110*Math.sin(t),'#b1c39c');}out='单位圆盘：0≤r≤1，0≤θ≤2π；面积元r dr dθ，面积π。相同角宽在外侧覆盖更多面积。';}}
if(type==='line'){const end=v('angle')*Math.PI/180,sign=v('direction');const pts=[];for(let i=0;i<=100;i++){const t=end*i/100;pts.push([280+105*Math.cos(t),155-105*Math.sin(t)]);}body=`<circle cx="280" cy="155" r="105" fill="none" stroke="#d6e1c9"/>`+plot(pts,'#397a60',4)+circle(385,155,5,'#7599ac')+circle(280+105*Math.cos(end),155-105*Math.sin(end),5)+textAt(30,30,sign===1?'正向：0 → θ':'反向：θ → 0');out=`弧长∫ds=θ=${num(end,6)}，反向仍为此值；第二型∫xdy−ydx=${num(sign*end,6)}。蓝点为角度0端点。`;}
if(type==='surface'){const a=v('a'),b=v('b'),sign=v('sign');const pr=(x,y,z)=>[260+90*x-65*y,225-32*x-25*y-35*z],pts=[[0,0,0],[1,0,a],[1,1,a+b],[0,1,b]].map(p=>pr(...p));body=`<polygon points="${pts.map(p=>p.join(',')).join(' ')}" fill="#b4d08966" stroke="#719965"/>`+arrow(...pr(.5,.5,(a+b)/2),...pr(.5-.45*a*sign,.5-.45*b*sign,(a+b)/2+.45*sign))+line(...pr(0,0,0),...pr(1.5,0,0))+line(...pr(0,0,0),...pr(0,1.5,0));out=`曲面面积=√(1+a²+b²)=${num(Math.sqrt(1+a*a+b*b))}；向${sign===1?'上':'下'}向量面积元=${sign===1?'':'−'}(−a,−b,1)dxdy。F=(0,0,1)的通量=${sign}，与倾斜角度无关。`;}
el.querySelector('.lab-canvas').innerHTML=svgBase(body,LABS[type][1]);el.querySelector('.lab-output').textContent=out;
}
function parseNumber(input){const raw=String(input).trim().replace(/−/g,'-').replace(/×/g,'*').replace(/÷/g,'/').replace(/π/g,'pi');if(!raw||raw.length>100)throw Error('请输入数值、分数或简单算式。');const tokens=raw.match(/(?:\d*\.\d+|\d+\.?\d*)(?:e[+-]?\d+)?|pi|sqrt|[()+\-*/^]/gi);if(!tokens||tokens.join('').toLowerCase()!==raw.replace(/\s+/g,'').toLowerCase())throw Error('支持数字、分数、+ − × ÷、括号、pi、sqrt(2)，请勿输入单位或等号。');let i=0;function primary(){const t=tokens[i++];if(t==='('){const n=expr();if(tokens[i++]!==')')throw Error('括号不匹配');return n;}if(t?.toLowerCase()==='pi')return Math.PI;if(t?.toLowerCase()==='sqrt'){if(tokens[i++]!=='(')throw Error('写成sqrt(2)');const n=expr();if(tokens[i++]!==')')throw Error('括号不匹配');return Math.sqrt(n);}if(t===undefined||!Number.isFinite(Number(t)))throw Error('算式不完整');return Number(t);}function pow(){let n=primary();if(tokens[i]==='^'){i++;n=n**unary();}return n;}function unary(){if(tokens[i]==='-'){i++;return -unary();}if(tokens[i]==='+'){i++;return unary();}return pow();}function product(){let n=unary();while(tokens[i]==='*'||tokens[i]==='/'){const op=tokens[i++],b=unary();n=op==='*'?n*b:n/b;}return n;}function expr(){let n=product();while(tokens[i]==='+'||tokens[i]==='-'){const op=tokens[i++],b=product();n=op==='+'?n+b:n-b;}return n;}const n=expr();if(i!==tokens.length||!Number.isFinite(n))throw Error('结果不是有限数，或算式格式有误');return n;}
function rref(matrix){let a=matrix.map(r=>[...r]),row=0,logs=[{op:'原矩阵',matrix:a.map(r=>[...r])}],cols=[];for(let col=0;col<a[0].length&&row<a.length;col++){let best=row;for(let i=row+1;i<a.length;i++)if(Math.abs(a[i][col])>Math.abs(a[best][col]))best=i;if(Math.abs(a[best][col])<1e-9)continue;if(best!==row){[a[best],a[row]]=[a[row],a[best]];logs.push({op:`交换 r${row+1} 与 r${best+1}`,matrix:a.map(r=>[...r])});}const pivot=a[row][col];a[row]=a[row].map(x=>x/pivot);if(Math.abs(pivot-1)>1e-9)logs.push({op:`r${row+1} 除以 ${num(pivot,6)}`,matrix:a.map(r=>[...r])});for(let i=0;i<a.length;i++){if(i===row)continue;let k=a[i][col];if(Math.abs(k)<1e-9)continue;a[i]=a[i].map((x,j)=>{let n=x-k*a[row][j];return Math.abs(n)<1e-9?0:n;});logs.push({op:`r${i+1} ← r${i+1} − (${num(k,6)}) r${row+1}`,matrix:a.map(r=>[...r])});}cols.push(col);row++;}return{matrix:a,rank:row,logs,pivots:cols};}
function fraction(x){if(Math.abs(x)<1e-9)return'0';for(let d=1;d<=200;d++){let n=Math.round(x*d);if(Math.abs(x-n/d)<1e-8)return d===1?String(n):`${n}/${d}`;}return num(x,6);}
function runRref(el){try{const rows=el.querySelector('textarea').value.trim().split(/\n|;/).filter(s=>s.trim()).map(s=>s.trim().split(/[\s,，]+/).map(parseNumber));if(!rows.length||rows.length>8||rows[0].length>10||!rows[0].length||rows.some(r=>r.length!==rows[0].length||r.some(x=>Math.abs(x)>1e6)))throw Error('请保证每行列数一致，最多8行10列，元素绝对值≤100万。');const result=rref(rows);el.querySelector('.lab-output').textContent=`整个输入矩阵的秩=${result.rank}；主元列（从1计）=${result.pivots.map(i=>i+1).join('、')||'无'}。共${result.logs.length-1}步行操作。增广矩阵中若常数列为主元列，应另行检查矛盾行。使用浮点运算并近似显示分数；极接近0的数需用精确代数复核。`;el.querySelector('.rref-steps').innerHTML=result.logs.map((log,i)=>`<details ${i===result.logs.length-1?'open':''}><summary class="small">${i}. ${esc(log.op)}</summary><pre class="lab-table">${log.matrix.map(r=>r.map(n=>fraction(n).padStart(9)).join(' ')).join('\n')}</pre></details>`).join('');}catch(e){el.querySelector('.lab-output').textContent=e.message;}}
function labPage(type){return heading('THE MATH LAB','让公式，在眼前动起来。','每个实验对应一种数学结构。图像用于建立直觉，严格结论仍要结合定义、公式条件和计算过程。')+`<div class="tabs">${Object.entries(LABS).map(([k,v])=>`<a href="#lab/${k}" class="${(type||'derivative')===k?'active':''}">${v[0]}</a>`).join('')}</div>${labHTML(LABS[type]?type:'derivative')}<div class="section-heading"><h2>相关课程</h2></div><div class="lesson-list">${C.filter(l=>l.visual===(type||'derivative')).map(card).join('')}</div>`;}
function collections(which){if(which==='favorites')return heading('SAVED FOR LATER','收藏夹','把想回看的解释放在一起。收藏只保存在当前浏览器，可随进度一起备份。')+(state.favorites.length?`<div class="lesson-list">${state.favorites.map(byId).filter(Boolean).map(card).join('')}</div>`:empty('☆','还没有收藏','进入一节课，点击“收藏本节”，便可在这里快速找到。','#chapters','去选一节课'));const keys=wrongKeys();return heading('LEARN FROM MISTAKES','每一道错题，都是一个入口。','答错的题会自动记录；再次答对后移入“已订正”。先写完整过程，再核对数值检查点。')+`<div class="toolbar"><button class="btn secondary small" id="toggle-resolved">查看已订正题</button><a class="btn secondary small" href="#day/21">按薄弱点复习</a></div><div id="mistake-list">${mistakeList(keys)}</div>`;}
function mistakeList(keys){return keys.length?keys.map(key=>{const[id,i]=key.split(':'),l=byId(id),a=state.attempts[key];if(!l||!l.exercises[i])return'';return `<section class="panel" style="margin-bottom:18px"><div class="actions"><a class="text-link" href="#lesson/${id}">${esc(l.chapter)} · ${esc(l.title)} ↗</a><span class="tag">答错${a.wrong}次${a.resolved?' · 已订正':''}</span></div>${exerciseHTML(l,Number(i))}</section>`;}).join(''):empty('✓','这里暂时没有题目','先完成几道练习，系统会帮你记录答错的题。','#chapters','开始练习');}
function empty(symbol,title,sub,url,label){return `<div class="empty"><div class="symbol">${symbol}</div><h3>${title}</h3><p class="small muted">${sub}</p><a class="btn secondary" href="${url}">${label}</a></div>`;}
function reviewPage(day){const weights=C.map(l=>({l,n:l.exercises.reduce((s,_,i)=>s+(state.attempts[l.id+':'+i]?.wrong||0),0),pending:l.exercises.filter((_,i)=>state.attempts[l.id+':'+i]?.wrong&&!state.attempts[l.id+':'+i]?.resolved).length})).filter(x=>x.pending).sort((a,b)=>b.pending-a.pending||b.n-a.n);const runs=state.examRuns.filter(r=>r.day===day);return heading(`DAY ${day} / 21`,DAYS[day-1],day===20?'自编综合测试，不是往年真题。18题覆盖全部六个模块，建议90分钟答题、60分钟订正、60分钟回看。':'先做第二套自编测试（12题、60分钟），再用90分钟重学薄弱点、45分钟错题重做、15分钟口述总结。')+`<div class="panel"><h2>${day===20?'综合测试 A':'复习测试 B'}</h2><p>题目为各节分层练习的选题，自动评分只检查数值。请在纸上保留计算过程；解释题与长证明需另作人工复盘。</p><div class="actions"><a class="btn" href="#exam/${day}">${state.activeExam?.day===day?'继续测试':'开始测试'} →</a><a class="btn secondary" href="#mistakes">直接复习错题</a></div>${runs.length?`<div class="result-summary small">最近一次：${runs.at(-1).correct}/${runs.at(-1).total}题正确，得分${runs.at(-1).score}。${new Date(runs.at(-1).at).toLocaleString('zh-CN')}</div>`:''}</div><div class="section-heading"><h2>需要优先回看的课程</h2></div>${weights.length?`<div class="panel">${weights.slice(0,8).map(x=>`<div class="weak-item"><div><a href="#lesson/${x.l.id}" class="text-link">${esc(x.l.title)}</a><div class="small muted">${x.pending}题待订正，历史答错${x.n}次</div></div><a class="btn small secondary" href="#lesson/${x.l.id}">回看</a></div>`).join('')}</div>`:empty('⌁','先用测试找到薄弱点','还没有待订正的错题。也可以回看未标记已学的课程。','#chapters','查看课程')}<div class="section-heading"><h2>最后复习时，请能回答这六个问题</h2></div><div class="panel"><ol class="proof-list"><li>为什么导数和定积分通过基本定理联系在一起？</li><li>矩阵的秩怎样决定方程有解与自由变量个数？</li><li>向量、代数方程与微分方程的“线性”有什么共同点？</li><li>特征值如何决定二次型、极值与动力系统的行为？</li><li>为什么极坐标和球坐标的面积元、体积元要多乘因子？</li><li>遇到边界积分时，怎样决定用Green、Gauss还是Stokes？</li></ol></div>`;}
const EXAM_A=[1,4,8,10,13,15,17,19,21,23,25,28,30,33,35,37,40,43];
const EXAM_B=[0,6,9,14,18,22,26,29,32,36,39,42];
function startExam(day){const ix=day===20?EXAM_A:EXAM_B;return{day,keys:ix.map((n,i)=>C[n].id+':'+(i%3)),inputs:{},remaining:day===20?5400:3600,finished:false};}
function examPage(day){if(![20,21].includes(day))return notFound();if(!state.activeExam||state.activeExam.day!==day)state.activeExam=startExam(day);examSession=state.activeExam;save();return heading('EXAM PRACTICE',day===20?'综合模拟 A':'复习测试 B','先独立完成。计时只在此页面可见且活动时推进；超过建议时间仍可提交。刷新可继续，本次测试成绩在提交后保存。')+`<div class="exam-top"><span id="exam-timer">剩余 ${formatTime(examSession.remaining)}</span><span>${examSession.keys.length}题 · 不限提示以外的纸笔计算</span><button class="btn small" id="submit-exam">提交评分</button></div><div id="exam-result"></div><div id="exam-questions">${examSession.keys.map((k,i)=>{let[id,j]=k.split(':'),l=byId(id);return `<h3 style="margin-top:25px">第${i+1}题 <span class="meta">${l.chapter}</span></h3>${exerciseHTML(l,Number(j),true)}`;}).join('')}</div><button class="btn" id="submit-exam-bottom">完成并提交</button>`;}
function formatTime(t){return t<=0?'已超过建议时间':String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');}
function record(key,input,ok){const prev=state.attempts[key]||{wrong:0,tries:0,resolved:false};state.attempts[key]={...prev,tries:prev.tries+1,wrong:prev.wrong+(ok?0:1),resolved:ok,lastInput:input,lastAt:new Date().toISOString()};}
function checkExercise(el){const key=el.dataset.key,[id,i]=key.split(':'),ex=byId(id).exercises[i],input=el.querySelector('input').value,fb=el.querySelector('.feedback');try{const n=parseNumber(input),ok=Math.abs(n-ex.answer)<=Math.max(1e-7,Math.abs(ex.answer)*1e-5);record(key,input,ok);save();fb.className='feedback '+(ok?'ok':'no');fb.textContent=ok?'✓ 数值检查正确。请再检查你的计算过程与条件。':'这次的数值还不对，已记录到错题本。试着先展开一个提示，定位卡住的步骤。';}catch(e){fb.className='feedback no';fb.textContent=e.message;}}
function submitExam(){if(examSession?.finished)return;let correct=0;const entries=[];document.querySelectorAll('.exercise[data-exam]').forEach(el=>{const key=el.dataset.key,[id,j]=key.split(':'),ex=byId(id).exercises[j],input=el.querySelector('input').value;let ok=false;try{ok=Math.abs(parseNumber(input)-ex.answer)<=Math.max(1e-7,Math.abs(ex.answer)*1e-5);}catch(e){}record(key,input,ok);if(ok)correct++;el.querySelector('input').disabled=true;el.querySelector('[data-check]').hidden=true;const fb=el.querySelector('.feedback');fb.className='feedback '+(ok?'ok':'no');fb.textContent=ok?'✓ 正确':'未答对或未作答。正确检查点：'+ex.answer;el.insertAdjacentHTML('beforeend',`<details><summary>查看完整解答</summary>${stepsHTML(ex.solution)}<a class="text-link" href="#lesson/${id}">回看本节 →</a></details>`);entries.push({key,ok,input});});examSession.finished=true;const score=Math.round(correct/entries.length*100);state.examRuns.push({day:examSession.day,correct,total:entries.length,score,entries,at:new Date().toISOString()});state.activeExam=null;save();$('#exam-result').innerHTML=`<div class="result-summary"><h2>本次得分 ${score} / 100</h2><p>${correct}/${entries.length}题数值检查正确。答错与未答题已加入错题本，逐题展开可查看过程。</p><div class="actions"><a class="btn secondary" href="#day/21">按薄弱点复习</a><a class="btn secondary" href="#mistakes">查看错题</a></div></div>`;$('#exam-result').scrollIntoView({behavior:'smooth'});document.querySelectorAll('#submit-exam,#submit-exam-bottom').forEach(b=>b.disabled=true);}
function backupPage(){return heading('YOUR LEARNING RECORD','学习进度，由你保存。','所有记录保存在当前浏览器，本网站不上传学习数据。清除浏览器数据、更换设备或不同站点地址都可能使本地记录不可见，请定期导出。')+`<div class="mini-grid"><section class="panel"><h2>导出进度备份</h2><p class="small">包含已学课程、收藏、错题、笔记、测试结果及累计学习时间。建议每隔2—3天保存一次。</p><button class="btn" id="export-backup">下载 JSON 备份 ↓</button><p class="small muted" style="margin-top:15px">最近保存：${esc(new Date(state.updated).toLocaleString('zh-CN'))}</p></section><section class="panel"><h2>从备份恢复</h2><p class="small">选择本站导出的JSON文件。导入前会检查格式，并列出记录数量；确认导入后替换当前浏览器记录。</p><input id="import-backup" type="file" accept="application/json,.json" aria-label="选择进度备份文件"><div id="import-preview"></div></section></div><section class="panel" style="margin-top:22px"><h3>跨设备继续学</h3><ol class="proof-list small"><li>在旧设备导出JSON文件。</li><li>把文件通过你习惯的方式传到新设备。</li><li>在新设备打开同一网站，选择“从备份恢复”。</li><li>确认导入数量后继续学习；内容笔记不会自动同步到ChatGPT聊天。</li></ol></section>`;}
function download(name,text,mime='application/json'){const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function validBackup(s){const ids=new Set(C.map(l=>l.id));if(!s||s.version!==VERSION||!Array.isArray(s.done)||!Array.isArray(s.favorites)||typeof s.attempts!=='object'||!s.attempts||typeof s.notes!=='object'||!s.notes||!Array.isArray(s.examRuns)||!Number.isFinite(s.studySeconds)||s.studySeconds<0)throw Error('备份格式不兼容或字段缺失，请使用本站导出的文件。');if([...s.done,...s.favorites].some(id=>!ids.has(id)))throw Error('备份包含不属于当前课程的记录。');for(const[k,a]of Object.entries(s.attempts)){const[id,j]=k.split(':');if(!ids.has(id)||!/^\d+$/.test(j)||!byId(id)?.exercises[Number(j)]||!a||!Number.isFinite(a.wrong)||a.wrong<0||!Number.isFinite(a.tries)||typeof a.resolved!=='boolean')throw Error('答题记录格式不正确。');}for(const[k,v]of Object.entries(s.notes))if(!ids.has(k)||typeof v!=='string')throw Error('笔记格式不正确。');return{...defaultState(),...s,done:[...new Set(s.done)],favorites:[...new Set(s.favorites)],activeExam:null};}
const COVERAGE=[['1.1','向量代数',1,'vector'],['1.1.1','数量积',2,'dot'],['1.1.2','向量积',4,'cross'],['1.1.3','混合积',5,'cross'],['1.2','矩阵',5,'matrix'],['1.2.1','矩阵运算',6,'matrix'],['1.2.2','方阵的行列式',10,'det'],['1.2.3','分块矩阵',14,'block'],['2.1','方程组理论',19,'row'],['2.1.1','矩阵的初等变换',20,'row'],['2.1.2','线性方程组解的存在性',27,'existence'],['2.2','空间中的平面、直线与曲面、曲线',30,'plane'],['2.2.1','平面方程',30,'plane'],['2.2.2','直线方程',32,'plane'],['2.2.3','曲面方程',34,'surfaces'],['2.2.4','曲线方程',42,'surfaces'],['3.1','线性相关性',45,'dependence'],['3.1.1','线性方程组解的结构',48,'structure'],['3.2','常微分方程',52,'separable'],['4.1','相似对角矩阵与特征值',65,'eigen'],['4.1.1','特征值与特征向量',65,'eigen'],['4.1.2','相似矩阵',68,'similar'],['4.1.3','二次型理论',69,'quadratic'],['4.2','一阶常系数微分方程组',73,'systems'],['4.3','多元函数及其偏导数',75,'partial'],['4.3.1','偏导数的概念',75,'partial'],['4.3.2','隐函数求导',78,'implicit'],['4.3.3','方向导数与梯度',79,'gradient'],['4.4','极值理论',81,'extrema'],['4.4.1','无条件极值',81,'extrema'],['4.4.2','条件极值',83,'lagrange'],['4.4.3','极值理论的应用',86,'regression'],['5.1','多重积分',89,'double'],['5.1.1','多重积分的基本概念',89,'double'],['5.1.2','二重积分',91,'double'],['5.1.3','三重积分',94,'triple'],['5.2','曲线积分',96,'lineintegral'],['5.2.1','Green公式',99,'green'],['5.3','曲面积分',100,'surfaceintegral'],['5.3.1','Gauss公式',103,'gauss'],['5.4','级数理论',106,'series'],['5.4.1','数项级数',106,'series'],['5.4.2','函数项级数',107,'taylor']];
function about(){return heading('SOURCE & NOTES','教材说明与讲义勘误','依据袁伟《高等数学与线性代数五讲-v2》编写。本文档仅服务于你的个人学习，数学解释与练习为补充编写。')+`<section class="panel"><h2>这份网站包含什么</h2><p>44节课程、${exerciseTotal()}道基础/典型/综合数值练习、16种交互实验、21天完整路径、第二讲起的12天紧凑路径和两套练习选题测试。按教材顺序保留五讲结构，并额外补入7节微积分基础。主要例题已在正文或“深入理解”中解释；部分较长原例的逐行展开另列在相关例题折叠区。</p><p>本网站把讲义作为来源，不把所有原文表述视为无条件正确。下方记录已核对的关键更正；原始PDF保留原貌，网站中的答案采用更正后的版本。图像用于帮助理解，不能替代严格证明。</p><p class="small muted">自动检查的对象是指定数值检查点，不是你在纸上写的全套证明。标记“已学”由你主动操作，浏览和答对一题都不会自动表示整节掌握。</p><div class="actions"><a class="btn secondary" href="source.pdf" target="_blank" rel="noopener">原始讲义PDF ↗</a><a class="btn secondary" href="math-five-lectures-source.zip" download>下载静态网站源码 ↓</a></div></section><section class="panel" style="margin-top:22px"><h2>关键更正与补充条件</h2><table class="coverage-table"><thead><tr><th>印刷页</th><th>位置</th><th>本网站采用的更正</th></tr></thead><tbody><tr><td>30</td><td>例2.9(iii)</td><td>特解应为(1,2,0)，原印(1,0,0)代回不成立。</td></tr><tr><td>41</td><td>球面参数</td><td>φ是与z轴夹角，即极角/余纬；地理纬度为π/2−φ。</td></tr><tr><td>50—51</td><td>例3.8、3.9</td><td>以系数矩阵(1,2,3)为准，式中的−3x₃应为+3x₃。</td></tr><tr><td>66</td><td>例4.1</td><td>矩阵中间对角元素为0，所以A−λI中应为−λ；特征值为0与1±√3。</td></tr><tr><td>73</td><td>二次型</td><td>半正定、半负定与不定分开；不定必须同时有正、负取值。</td></tr><tr><td>79</td><td>梯度几何意义</td><td>二元标量场梯度为(fx,fy)；(fx,fy,−1)是图像曲面的法向量。</td></tr><tr><td>84—85</td><td>极值证明</td><td>比较单个点不足以判极值，本网站用配方和约束上不等式证明。</td></tr><tr><td>88</td><td>最小二乘唯一性</td><td>需xᵢ不全部相同，才能保证Hessian正定、斜率截距唯一。</td></tr><tr><td>103</td><td>法向记号</td><td>(−fx,−fy,1)非单位法向；与面积元组合时应明确单位化。</td></tr><tr><td>106</td><td>比值判别</td><td>需比值极限&lt;1或尾部有统一小于1的上界；逐项比值&lt;1并不足够。</td></tr><tr><td>107</td><td>ln(1+x)级数</td><td>从n=1开始时分母为n，收敛域−1&lt;x≤1，另需区分Taylor级数与函数相等条件。</td></tr></tbody></table></section><section class="panel" style="margin-top:22px"><h2>讲义章节对应表</h2><p class="small muted">下列为原有章节编号，点击即可进入对应课程。正文打印页p.n对应PDF文件第n+4页。</p><table class="coverage-table"><thead><tr><th>原编号</th><th>知识点</th><th>印刷页</th><th>课程</th></tr></thead><tbody>${COVERAGE.map(([n,t,p,id])=>`<tr><td>${n}</td><td>${t}</td><td><a href="source.pdf#page=${p+4}" target="_blank" rel="noopener">${p} ↗</a></td><td><a class="text-link" href="#lesson/${id}">进入详解 →</a></td></tr>`).join('')}</tbody></table><p class="small muted" style="margin-top:15px">讲义附录A为内容概要，复习时可查原PDF p.109—111；主要课程覆盖表以上述正文为准。Stokes公式虽未单列目录编号，也已在5.3.1课程中补入。</p></section><section class="panel" style="margin-top:22px"><h2>部署到GitHub Pages</h2><ol class="proof-list"><li>下载源码ZIP并解压。网站仅由HTML、CSS、JavaScript、字体和PDF组成，无需服务器、构建或API密钥。</li><li>在你确认的新GitHub仓库中上传解压后 dist/ 里面的全部网站文件，保证index.html在仓库根目录。</li><li>进入Settings → Pages，选择Deploy from a branch，分支main、目录/(root)，保存。</li><li>等待GitHub部署完成后，用它提供的网址访问。更换地址或设备时，先导出进度JSON再导入。</li></ol><p class="small muted">本次没有修改或覆盖你的其他GitHub项目。本站使用独立GitHub Pages项目。学习记录仅保存在当前浏览器，可从原网站导出JSON后导入。</p></section>`;}
const SPRINT=window.SPRINT;
const exerciseTotal=()=>C.reduce((n,l)=>n+l.exercises.length,0);
function sprintNext(){return SPRINT.find(s=>s.lessons.length&&!s.lessons.every(id=>state.done.includes(id)))||SPRINT[10];}
function sprintCard(s){const count=s.lessons.filter(id=>state.done.includes(id)).length;return `<a href="#sprint/${s.day}" class="day-card"><div class="actions"><span class="num">${String(s.day).padStart(2,'0')}</span><span class="tag">${s.chapter===6?'测试与查漏':'第'+['零','一','二','三','四','五'][s.chapter]+'讲'}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.goal)}</p><div class="card-bottom"><span>${s.day<=10?'3道核心题 · 其余选做':'测试 + 错题复盘'}</span><span>${s.lessons.length?`${count}/${s.lessons.length}节已学`:''} →</span></div></a>`;}
function home(){const s=sprintNext(),solved=Object.values(state.attempts).filter(a=>a.resolved).length;return `<div class="intro-line"><span class="eyebrow">FOCUSED EXAM PREPARATION</span><span class="date-badge">第二讲起 · 12天紧凑路线</span></div>${heading('','时间紧，先把主线抓住。','第一讲到第五讲均可学习；第一讲设有独立紧凑复习入口，第二至五讲按12天路线继续。每个学习日先完成3道核心题，详细解释与额外练习按需展开。')}<div class="panel" style="margin-bottom:22px"><h2>第一讲 · 向量代数与矩阵</h2><p>7节详细讲解 · 84道分层练习 · 向量与矩阵两组紧凑学习，随时回看。</p><a class="btn" href="#lecture1">进入第一讲学习与巩固 →</a></div><section class="hero"><div class="hero-copy"><span class="eyebrow">接着学 / 冲刺第 ${s.day} 天</span><h2>${esc(s.title)}</h2><p>${esc(s.goal)}</p><a class="btn light" href="#sprint/${s.day}">进入今天的紧凑学习 →</a></div><div class="hero-graph">${heroSvg()}</div></section><div class="stats"><div class="stat"><span class="stat-label">当前路线</span><div class="stat-num">12<small>天 · 从第二讲继续</small></div></div><div class="stat"><span class="stat-label">每日优先完成</span><div class="stat-num">3<small>道核心题</small></div></div><div class="stat"><span class="stat-label">完整巩固题库</span><div class="stat-num">${exerciseTotal()}<small>道 · 每节至少9道</small></div></div><div class="stat"><span class="stat-label">待订正错题</span><div class="stat-num">${wrongKeys().length}<small>道</small></div></div></div><div class="two-col"><section><div class="section-heading"><h2>今天只抓这几个方法</h2><a class="text-link" href="#sprint/${s.day}">集中学习 →</a></div><div class="lesson-list">${s.lessons.length?s.lessons.map(id=>card(byId(id))).join(''):'<a class="panel" href="#exam/20">进入综合测试 →</a>'}</div></section><section><div class="section-heading"><h2>不用把所有内容同时展开</h2></div><div class="panel"><ol class="proof-list small"><li>先看本日目标和代表例题。</li><li>独立完成3道核心题，检查过程。</li><li>卡住时再展开慢速演算与补充解释。</li><li>有余力再做本节其他6—8道题。</li></ol><div class="tip">教材保持详细，学习任务集中。每天以3—4小时为预算；是否能覆盖全部还取决于实际掌握速度。</div></div></section></div><div class="section-heading"><h2>第二讲到第五讲，集中走完</h2><a href="#sprint" class="text-link">查看12天安排 →</a></div><div class="day-grid">${SPRINT.slice(0,3).map(sprintCard).join('')}</div><div class="actions" style="margin-top:22px"><a class="btn secondary" href="#chapters">按讲查看紧凑目录</a><a class="text-link" href="#plan">保留的21天完整路线 →</a></div>`;}
function sprintPlan(){return heading('12-DAY FOCUSED PATH','从第二讲继续，集中学完剩下四讲。','先按约12天、每天3—4小时编排；实际考试日期未提供，可按剩余天数调整。前10天学习，第11—12天测试与查漏。')+`<div class="tip">每天必做3题。原有完整教材、慢速推导、9题巩固区都保留；长证明和重复训练按需展开。第四、五讲较密集，先完成核心题，再补薄弱方法。</div><div class="tabs" style="margin-top:20px"><a href="#sprint" class="active">紧凑冲刺路线</a><a href="#plan">原21天完整路线</a><a href="#chapters">按讲集中学习</a></div><div class="panel" style="margin:20px 0"><h2>先复习第一讲？</h2><p>向量、点积、叉积、矩阵、行列式与求逆，按两组集中回顾。</p><a class="btn secondary" href="#lecture1">第一讲紧凑学习与练习 →</a></div><div class="day-grid">${SPRINT.map(sprintCard).join('')}</div>`;}
function sprintDay(day){const s=SPRINT.find(x=>x.day===day);if(!s)return notFound();if(day>=11)return heading('冲刺第'+day+'天',s.title,s.focus)+`<div class="actions"><a class="btn" href="#day/${day===11?20:21}">进入${day===11?'综合模拟':'查漏复习'} →</a><a class="btn secondary" href="#mistakes">查看待订正错题</a></div>`;return heading(`紧凑冲刺 / 第${day}天 / 第${s.chapter}讲`,s.title,s.goal)+`<div class="tip">${esc(s.focus)}</div><div class="compact-budget"><span>20分钟 · 方法框架</span><span>90分钟 · 代表例题</span><span>45分钟 · 3道核心题</span><span>25分钟 · 订正回顾</span><span>余力选做 · 30—60分钟</span></div><div class="section-heading"><h2>在这一页，按方法顺序学</h2><span class="small muted">展开需要的单元即可</span></div>${s.lessons.map((id,i)=>{const l=byId(id);return `<details class="compact-unit" ${i===0?'open':''}><summary><span class="pill">${l.chapter}</span><strong>${esc(l.title)}</strong><span class="small">展开主线 ↓</span></summary><div class="compact-content"><h3>先会这三件事</h3><ul class="goal-list">${l.goals.map(g=>`<li>${esc(g)}</li>`).join('')}</ul><h3 style="margin-top:22px">本方法先怎样想</h3>${l.slowNotes.slice(0,1).map(P).join('')}<h3>代表例题</h3><div class="example-box">${P(l.example)}</div>${stepsHTML(l.steps)}<details class="deep"><summary>这里没看懂？展开慢速演算与公式解释</summary>${l.slowNotes.slice(1).map(P).join('')}${P(l.slowExample.q)}${stepsHTML(l.slowExample.steps)}<h4>公式推导</h4>${stepsHTML(l.derive)}</details><div class="actions" style="margin-top:18px"><button class="btn small" data-mark-lesson="${id}">${state.done.includes(id)?'✓ 该方法已学':'标记该方法已学'}</button><a class="btn secondary small" href="#lesson/${id}">完整详解、交互与${l.exercises.length}题 →</a>${sourceLink(l)}</div></div></details>`;}).join('')}<section class="panel" style="margin-top:28px"><h2>今天先做这3题</h2><p class="small muted">先在纸上写过程，再输入题目要求的数值。不是要求今天把所有题都刷完。</p>${s.core.map(k=>{const[id,j]=k.split(':');return `<a class="text-link small" href="#lesson/${id}">${esc(byId(id).title)} ↗</a>${exerciseHTML(byId(id),Number(j))}`;}).join('')}</section><div class="panel" style="margin-top:20px"><h3>今天的完成标准</h3><p>能说清本日每个方法的适用条件，能不看答案重做一个代表例题，3道核心题已理解或明确记下卡点。完成标记仍在各节完整教材中保留。</p><div class="actions"><a class="btn secondary" href="#sprint">返回集中安排</a><a class="btn" href="#sprint/${Math.min(day+1,12)}">下一天 →</a></div></div>`;}
function chapters(){return heading('LECTURE-FIRST LEARNING','按讲集中学习，细节需要时再展开。','第一讲目录直接展开，可进入两组紧凑学习；第二至五讲沿用12天冲刺路线。完整44节教材均可按需学习。')+CHAPTERS.map((name,i)=>{const ls=C.filter(l=>l.chapter.startsWith(String(i))),days=SPRINT.filter(s=>s.chapter===i);return `<section class="chapter-block" id="chapter-${i}"><div class="section-heading"><h2>${name}</h2><span class="tag">${ls.length}节详细教材</span></div>${i===1?'<p><a class="btn" href="#lecture1">第一讲紧凑学习与巩固 →</a></p>':''}${days.length?`<div class="lesson-list">${days.map(s=>`<a class="lesson-card" href="#sprint/${s.day}"><span class="lesson-icon">${s.day}</span><div class="grow"><h3>${esc(s.title)}</h3><div class="meta">集中主线 · 3道核心题 · 细节按需展开</div></div><span class="arrow">→</span></a>`).join('')}</div>`:'<p class="small muted">可随时学习或回顾，不占用第二至五讲的12天冲刺日程。</p>'}<details class="deep" ${i===1?'open':''} style="margin-top:13px"><summary>展开本讲完整目录、详细解释与练习</summary><div class="lesson-list" style="margin-top:15px">${ls.map(card).join('')}</div></details></section>`;}).join('');}


function firstLecture(){const groups=[{title:'第一组 · 向量运算',goal:'掌握坐标运算，用点积求夹角与投影，用叉积求面积与法向量，用混合积求体积。',ids:['vector','dot','cross'],core:['vector:9','dot:11','cross:10']},{title:'第二组 · 矩阵、行列式与求逆',goal:'先检查维数再做矩阵乘法，分清转置与逆，利用行列式判断可逆性，掌握伴随矩阵和分块运算。',ids:['matrix','rotation','det','block'],core:['matrix:10','det:11','block:11']}];return heading('LECTURE 01 / 1.1—1.2.3','第一讲 · 向量代数与矩阵','讲义印刷p.1—17（PDF文件第5—21页）。7节详细教材、84道练习全部保留，按两组集中学习。')+`<div class="tip">已学过可用每组60—90分钟回顾；首次学习建议每组3—4小时，难点随时展开详细步骤。先做每组3道核心题，再按薄弱点进入各节12题巩固。完成情况由你自行标记，不预设第一讲已完成。</div><div class="actions" style="margin:20px 0"><a class="btn secondary" href="#chapters">全部章节</a><a class="text-link" href="#sprint/1">继续第二讲 →</a></div>${groups.map(g=>`<section class="chapter-block"><h2>${g.title}</h2><p>${g.goal}</p>${g.ids.map((id,i)=>{const l=byId(id);return `<details class="compact-unit" ${i===0?'open':''}><summary><span class="pill">${l.chapter}</span><strong>${esc(l.title)}</strong><span class="small">展开学习 ↓</span></summary><div class="compact-content"><h3>本节目标</h3><ul class="goal-list">${l.goals.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>从概念开始</h3>${l.concept.map(P).join('')}<details class="deep"><summary>零基础细讲 · 符号、公式与逐步推导</summary>${l.slowNotes.map(P).join('')}<h4>逐步推导</h4>${stepsHTML(l.derive)}</details><h3>代表例题 · 完整计算过程</h3><div class="example-box">${P(l.example)}</div>${stepsHTML(l.steps)}<details class="deep"><summary>再看一道慢速演算</summary>${P(l.slowExample.q)}${stepsHTML(l.slowExample.steps)}</details><h3>常见错误与检查方法</h3><ul>${l.errors.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><div class="actions"><button class="btn small" data-mark-lesson="${id}">${state.done.includes(id)?'✓ 该方法已学':'标记该方法已学'}</button><a class="btn secondary small" href="#lesson/${id}">完整详解、交互图形与12道练习 →</a>${sourceLink(l)}</div></div></details>`;}).join('')}<div class="panel" style="margin-top:22px"><h3>本组先做这3题</h3><p class="small muted">独立写出过程，再检查答案；可逐步查看提示，答案在折叠区中。</p>${g.core.map(k=>{const[id,j]=k.split(':');return `<a class="text-link" href="#lesson/${id}">${esc(byId(id).title)} · 全部12题 →</a>${exerciseHTML(byId(id),Number(j))}`;}).join('')}</div></section>`).join('')}<div class="panel"><h2>第一讲学完后</h2><p>能独立完成向量投影、面积或体积、矩阵乘法与二阶求逆，再进入第二讲的高斯消元；卡住的题可加入错题本反复练习。</p><a class="btn" href="#sprint/1">进入第二讲 · 消元、秩与解的个数 →</a></div>`;}

function notFound(){return empty('∅','没有找到这个页面','请从课程目录重新选择。','#home','回到学习总览');}
function route(){currentId=null;examSession=null;document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');const hash=location.hash.slice(1)||'home';const[page,arg]=hash.split('/');let html;switch(page){case'home':html=home();break;case'plan':html=plan();break;case'sprint':html=arg?sprintDay(Number(arg)):sprintPlan();break;case'day':html=dayPage(Number(arg));break;case'chapters':html=chapters();break;case'lecture1':html=firstLecture();break;case'lesson':html=lessonPage(byId(arg));break;case'lab':html=labPage(arg);break;case'mistakes':case'favorites':html=collections(page);break;case'backup':html=backupPage();break;case'about':html=about();break;case'exam':html=examPage(Number(arg));break;default:html=notFound();}
$('#main').innerHTML=html;$('#breadcrumb').textContent=page==='lesson'?`${byId(arg)?.chapter||''} / 课程详解`:({home:'我的数学自习室',plan:'学习路径 / 21天计划',chapters:'全部课程 / 章节目录',lecture1:'第一讲 / 向量代数与矩阵',lab:'探索 / 数学实验室',mistakes:'学习记录 / 错题本',favorites:'学习记录 / 收藏夹',backup:'学习记录 / 备份与恢复',about:'教材说明 / 来源与勘误',exam:'模拟练习 / 综合测试',day:'学习路径 / 每日安排',sprint:'学习路径 / 紧凑冲刺'}[page]||'我的数学自习室');document.querySelectorAll('#primary a').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||(page==='day'||page==='exam'||page==='sprint')&&a.dataset.nav==='plan'||page==='lesson'&&a.dataset.nav==='chapters'));document.title=(page==='lesson'?byId(arg)?.title:page==='day'?`第${arg}天 · ${DAYS[Number(arg)-1]}`:'五讲 · 数学自习室')+' | 紧凑冲刺数学学习';updateSide();bindPage();document.querySelectorAll('[data-lab]').forEach(drawLab);window.scrollTo(0,0);renderedAt=Date.now();}
async function copyQuestion(l,key){let q=$('#ask-question')?.value.trim()||'请用适合零基础的中文解释我卡住的地方，不省略代数计算步骤。';let text=`我正在学习《高等数学与线性代数五讲》。\n章节：${l.chapter} ${l.title}\n学习日：${learningDayLabel(l)}\n来源：${pagesLabel(l)}\n\n相关概念：\n${l.concept.join('\n')}\n\n细化解释：\n${l.slowNotes.join('\n')}\n\n重要公式与推导：\n${l.derive.join('\n')}\n\n本节例题：${l.example}\n${l.steps.map((s,i)=>`${i+1}. ${s}`).join('\n')}\n`;
if(key){const j=Number(key.split(':')[1]),e=l.exercises[j];const block=[...document.querySelectorAll('.exercise')].find(el=>el.dataset.key===key);text+=`\n我正在做的题：${e.q}\n我输入的答案：${block?.querySelector('input')?.value||'尚未作答'}\n`;}text+=`\n我的问题：${q}\n请先定位我需要补充的前置概念，再逐步回答。`;
try{if(!navigator.clipboard)throw Error('clipboard unavailable');await navigator.clipboard.writeText(text);toast('已复制完整提问，请粘贴到ChatGPT聊天中。');}catch(e){const d=document.createElement('dialog');d.innerHTML=`<form method="dialog"><button class="close" aria-label="关闭">×</button></form><h2>手动复制提问</h2><p class="small muted">浏览器未开放剪贴板。长按或全选下方文字复制。</p><textarea class="question-copy" readonly aria-label="完整提问内容">${esc(text)}</textarea>`;document.body.append(d);d.showModal();d.querySelector('textarea').select();d.addEventListener('close',()=>d.remove());}}
function bindPage(){const main=$('#main');let shown={derive:1,example:1};main.onclick=e=>{const btn=e.target.closest('button,a');if(!btn)return;if(btn.dataset.practiceFilter){const level=btn.dataset.practiceFilter;document.querySelectorAll('#practice .exercise').forEach(el=>el.hidden=level!=='全部'&&el.dataset.level!==level);document.querySelectorAll('[data-practice-filter]').forEach(b=>b.classList.toggle('secondary',b!==btn));return;}if(btn.dataset.scroll){e.preventDefault();document.getElementById(btn.dataset.scroll)?.scrollIntoView({behavior:'smooth'});return;}if(btn.dataset.nextStep||btn.dataset.allStep){const kind=btn.dataset.nextStep||btn.dataset.allStep,l=byId(currentId),items=kind==='derive'?l.derive:l.steps;shown[kind]=btn.dataset.allStep?items.length:Math.min(items.length,shown[kind]+1);$(`#${kind==='derive'?'derive':'example'}-steps`).innerHTML=stepsHTML(items,shown[kind]);main.querySelector(`[data-next-step="${kind}"]`).disabled=shown[kind]===items.length;return;}if(btn.hasAttribute('data-check')){const el=btn.closest('.exercise');if(el.dataset.exam){toast('模拟测试请统一提交评分。');return;}checkExercise(el);return;}if(btn.hasAttribute('data-hint')){const el=btn.closest('.exercise'),[id,j]=el.dataset.key.split(':'),ex=byId(id).exercises[j],area=el.querySelector('.hint-area');const n=Number(area.dataset.n||0);if(n<ex.hints.length){area.insertAdjacentHTML('beforeend',P(`提示${n+1}：${ex.hints[n]}`));area.dataset.n=n+1;}if(n+1>=ex.hints.length)btn.disabled=true;return;}if(btn.dataset.askEx){const key=btn.dataset.askEx;copyQuestion(byId(key.split(':')[0]),key);return;}if(btn.hasAttribute('data-rref')){runRref(btn.closest('[data-lab]'));return;}if(btn.hasAttribute('data-rref-example')){const el=btn.closest('[data-lab]');el.querySelector('textarea').value='2 -1 -1 1 2\n1 1 -2 1 4\n4 -6 2 -2 4\n3 6 -9 7 9';runRref(el);return;}
if(btn.dataset.markLesson){const id=btn.dataset.markLesson;state.done=state.done.includes(id)?state.done.filter(v=>v!==id):[...state.done,id];save();btn.textContent=state.done.includes(id)?'✓ 该方法已学':'标记该方法已学';return;}if(btn.id==='mark-done'){state.done=state.done.includes(currentId)?state.done.filter(id=>id!==currentId):[...state.done,currentId];save();btn.textContent=state.done.includes(currentId)?'✓ 已标记已学':'标记本节已学';btn.classList.toggle('subtle',state.done.includes(currentId));return;}if(btn.id==='favorite'){state.favorites=state.favorites.includes(currentId)?state.favorites.filter(id=>id!==currentId):[...state.favorites,currentId];save();btn.textContent=state.favorites.includes(currentId)?'★ 已收藏':'☆ 收藏本节';return;}if(btn.id==='ask-top'){$('#ask-box').scrollIntoView({behavior:'smooth'});$('#ask-question').focus();return;}if(btn.id==='copy-question'){copyQuestion(byId(currentId));return;}if(btn.id==='toggle-resolved'){const resolved=btn.dataset.resolved!=='true';btn.dataset.resolved=resolved;btn.textContent=resolved?'查看待订正题':'查看已订正题';$('#mistake-list').innerHTML=mistakeList(Object.keys(state.attempts).filter(k=>state.attempts[k].wrong>0&&(resolved?state.attempts[k].resolved:!state.attempts[k].resolved)));return;}if(btn.id==='export-backup'){download(`数学学习进度-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(state,null,2));toast('进度备份已导出。');return;}if(btn.id==='submit-exam'||btn.id==='submit-exam-bottom'){submitExam();return;}};
main.oninput=e=>{const el=e.target;if(el.matches('[data-param]')){if(el.nextElementSibling?.tagName==='OUTPUT')el.nextElementSibling.textContent=el.value;drawLab(el.closest('[data-lab]'));}if(el.id==='lesson-note'){state.notes[currentId]=el.value;save();}if(el.closest('[data-exam]')&&examSession){examSession.inputs[el.closest('.exercise').dataset.key]=el.value;save();}};
main.onchange=async e=>{const el=e.target;if(el.matches('select[data-param]'))drawLab(el.closest('[data-lab]'));if(el.id==='import-backup'&&el.files[0]){try{if(el.files[0].size>5e6)throw Error('文件过大，请选择本站JSON备份。');const imported=validBackup(JSON.parse(await el.files[0].text()));$('#import-preview').innerHTML=`<div class="note">准备导入：${imported.done.length}节已学、${imported.favorites.length}个收藏、${Object.keys(imported.attempts).length}条答题记录。当前记录将被替换。</div><button class="btn small" id="confirm-import">确认导入这份备份</button>`;$('#confirm-import').onclick=()=>{state=imported;save();toast('已恢复学习进度。');route();};}catch(err){$('#import-preview').innerHTML=`<div class="note">${esc(err.message)}</div>`;}}};
if(examSession){document.querySelectorAll('.exercise[data-exam]').forEach(el=>{el.querySelector('input').value=examSession.inputs[el.dataset.key]||'';el.querySelector('[data-check]').hidden=true;});}
}
function search(q){const query=q.trim().toLowerCase();const list=query?C.filter(l=>(l.chapter+' '+l.title+' '+l.goals.join(' ')+' '+l.concept.join(' ')).toLowerCase().includes(query)):C.slice(0,6);$('#search-results').innerHTML=list.length?list.slice(0,12).map(card).join(''):'<p class="small muted">没有匹配课程。试试“积分”“矩阵”“特征值”或章节编号。</p>';$('#search-results').querySelectorAll('a').forEach(a=>a.onclick=()=>$('#search-dialog').close());}
function openSearch(){$('#search-dialog').showModal();$('#search-input').focus();search($('#search-input').value);}
$('#nav-backdrop').onclick=()=>{document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');};
$('#menu').onclick=()=>{const show=!document.body.classList.contains('menu-open');document.body.classList.toggle('menu-open',show);$('#menu').setAttribute('aria-expanded',String(show));};
$('#search-button').onclick=openSearch;$('#search-input').oninput=e=>search(e.target.value);document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menu').setAttribute('aria-expanded','false');}if(e.key==='/'&&!e.ctrlKey&&!e.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();openSearch();}});
window.addEventListener('hashchange',route);
setInterval(()=>{if(document.visibilityState!=='visible')return;state.studySeconds+=5;if(examSession&&!examSession.finished){examSession.remaining-=5;const t=$('#exam-timer');if(t)t.textContent='剩余 '+formatTime(examSession.remaining);}save();},5000);
window.MathRoom={parseNumber,rref,fraction,validBackup,rich,COURSE:C,COVERAGE,EXAM_A,EXAM_B,route};
route();
